+import assert from 'node:assert/strict';
+import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import path from 'node:path';
+import { after, before, describe, it } from 'node:test';
+import { getConfig, setConfig, watchConfig, type Config } from '../src/config.ts';
+
+const dir = mkdtempSync(path.join(tmpdir(), 'parcel-config-'));
+const file = path.join(dir, 'default.json');
+const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
+
+const write = (erpUrl: string, timeoutMs = 5000) =>
+  writeFileSync(file, JSON.stringify({ port: 3000, dataFile: 'data/store.json', erp: { url: erpUrl, timeoutMs } }));
+
+async function waitFor(check: () => boolean, ms = 3000): Promise<void> {
+  const until = Date.now() + ms;
+  while (!check()) {
+    if (Date.now() > until) assert.fail('condition not met in time');
+    await sleep(10);
+  }
+}
+
+describe('config hot reload', () => {
+  let original: Config;
+  let stop: () => void;
+
+  before(() => {
+    original = getConfig();
+    delete process.env.ERP_URL;
+    write('http://one.test/events');
+    setConfig({ ...original, erp: { url: 'http://initial.test/events', timeoutMs: 1 } });
+    stop = watchConfig({ file, intervalMs: 20 });
+  });
+
+  after(() => {
+    stop();
+    setConfig(original);
+    rmSync(dir, { recursive: true, force: true });
+  });
+
+  it('picks up a changed file without a restart', async () => {
+    await sleep(60);
+    write('http://two.test/events', 1234);
+    await waitFor(() => getConfig().erp.url === 'http://two.test/events');
+    assert.equal(getConfig().erp.timeoutMs, 1234);
+  });
+
+  it('keeps the previous config when the file is invalid, and recovers afterwards', async () => {
+    await sleep(60);
+    writeFileSync(file, '{ not json');
+    await sleep(150);
+    assert.equal(getConfig().erp.url, 'http://two.test/events');
+    await sleep(60);
+    write('http://three.test/events');
+    await waitFor(() => getConfig().erp.url === 'http://three.test/events');
+  });
+
+  it('stops reloading after the returned stop function is called', async () => {
+    stop();
+    await sleep(60);
+    write('http://four.test/events');
+    await sleep(150);
+    assert.equal(getConfig().erp.url, 'http://three.test/events');
+  });
+});
